<script setup lang="ts">
import { computed, ref } from 'vue'
import { useWorkbench } from './composables/useWorkbench'
import { formatNumber, formatTime, resultStatus } from './utils/presentation'
import type { View } from './types'
import AppIcon from './components/AppIcon.vue'
import SearchComposer from './components/SearchComposer.vue'
import AnswerPanel from './components/AnswerPanel.vue'
import InspectorPanel from './components/InspectorPanel.vue'
import DocumentDialog from './components/DocumentDialog.vue'

const {
  view, question, submittedQuestion, confirmed, running, elapsed, error, health,
  healthError, checkingHealth, result, history, storageNotice, ready, canRun,
  refreshHealth, submit, newSearch, openRecord, clearHistory,
} = useWorkbench()
const menuOpen = ref(false)
const composer = ref<InstanceType<typeof SearchComposer>>()
const documentDialog = ref<InstanceType<typeof DocumentDialog>>()
const helpDialog = ref<HTMLDialogElement>()
const navItems: { key: View; label: string; icon: string }[] = [
  { key: 'search', label: 'Research', icon: 'search' },
  { key: 'history', label: 'History', icon: 'history' },
  { key: 'baseline', label: 'System', icon: 'book' },
]
const title = computed(() => navItems.find(item => item.key === view.value)?.label || 'Research')
const serviceLabel = computed(() => healthError.value ? 'Connection unavailable' : !health.value ? 'Checking connection' : ready.value ? 'Ready to run' : 'Configuration needed')
const samples = [
  { title: 'Publication history', icon: 'book', detail: 'Establish authorship and the original publication date.', question: 'Who wrote Pride and Prejudice, and when was it first published?' },
  { title: 'Academic background', icon: 'network', detail: 'Identify a researcher’s university and fields of study.', question: 'Which university did Marie Curie attend in Paris, and what were her fields of study?' },
  { title: 'Institutional history', icon: 'layers', detail: 'Locate an organization’s headquarters and founding date.', question: 'Where is UNESCO headquartered, and when was it established?' },
]
function navigate(target: View) { view.value = target; menuOpen.value = false }
function startNew() { if (running.value) return; newSearch(); menuOpen.value = false; void composer.value?.focus() }
function useSample(value: string) { question.value = value; void composer.value?.focus() }
</script>

<template>
  <a class="skip-link" href="#main-content">Skip to content</a>
  <div class="app-shell">
    <aside class="sidebar" :class="{ 'mobile-open': menuOpen }" aria-label="Workspace navigation">
      <a class="brand" href="#" @click.prevent="navigate('search')"><span class="brand-symbol"><AppIcon name="layers" :size="23" /></span><span><strong>TRACE</strong><small>RESEARCH ENGINE</small></span></a>
      <button class="button new-search" :disabled="running" @click="startNew"><AppIcon name="plus" :size="18" />New question<kbd>NEW</kbd></button>
      <span class="nav-caption">Workspace</span>
      <nav class="main-nav"><button v-for="item in navItems" :key="item.key" :aria-current="view === item.key ? 'page' : undefined" :class="{ active: view === item.key }" @click="navigate(item.key)"><AppIcon :name="item.icon" :size="20" /><span>{{ item.label }}</span><span v-if="item.key === 'history' && history.length" class="nav-count">{{ history.length }}</span></button></nav>
      <div class="recent-section"><span class="nav-caption">Recent questions</span><div v-if="history.length" class="recent-list"><button v-for="record in history.slice(0, 4)" :key="record.id" :disabled="running" :title="record.question" @click="openRecord(record); menuOpen = false"><AppIcon name="file" :size="15" /><span>{{ record.question }}</span></button></div><p v-else class="recent-empty">Your recent questions will appear here.</p></div>
      <div class="sidebar-bottom"><div class="baseline-mini"><span class="baseline-mini-mark"><AppIcon name="shield" :size="21" /></span><div><strong>BM25 Baseline</strong><span>Retrieval grounded in a fixed corpus.</span></div></div><button class="sidebar-help" @click="helpDialog?.showModal(); menuOpen = false"><AppIcon name="help" :size="17" />Quick guide<AppIcon name="chevron" :size="14" /></button><p>COMP5423 · Search Agent</p></div>
    </aside>
    <button v-if="menuOpen" class="mobile-backdrop" aria-label="Close navigation" @click="menuOpen = false" />
    <div class="app-body">
      <header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-menu-button" aria-label="Open navigation" :aria-expanded="menuOpen" @click="menuOpen = !menuOpen"><AppIcon name="menu" /></button><span>Workspace</span><AppIcon name="chevron" :size="13" /><strong>{{ title }}</strong></div><div class="topbar-right"><span class="environment-label"><AppIcon name="shield" :size="14" />LOCAL CORPUS</span><button class="service-status" :class="ready ? 'ready' : healthError ? 'error' : 'pending'" aria-label="View service status" @click="navigate('baseline')"><span class="status-dot" /><span>{{ serviceLabel }}</span></button><span class="topbar-divider" /><button class="icon-button" aria-label="Open quick guide" @click="helpDialog?.showModal()"><AppIcon name="help" :size="19" /></button><span class="workspace-label">LOCAL SESSION</span></div></header>
      <main id="main-content" class="workspace" :class="{ 'full-view': view !== 'search' }">
        <section v-if="view === 'search'" class="workspace-main" :class="{ 'has-session': result || running || submittedQuestion }" aria-labelledby="workspace-title">
          <div class="page-heading"><div><p class="eyebrow">RESEARCH WORKSPACE</p><h1 id="workspace-title"><template v-if="!result && !running && !submittedQuestion">What would you like<br /><span>to investigate?</span></template><template v-else>Research session<span class="session-marker"> / Sources in context</span></template></h1><p class="page-description">Describe what you’re trying to establish. TRACE searches the corpus and brings the supporting evidence into context.</p></div><span class="heading-emblem" aria-hidden="true"><AppIcon name="layers" :size="34" /></span></div>
          <div class="workflow-strip" aria-label="Research workflow"><span><span class="step-icon"><AppIcon name="search" :size="16" /></span>Plan</span><i /><span><span class="step-icon"><AppIcon name="file" :size="16" /></span>Search</span><i /><span><span class="step-icon"><AppIcon name="shield" :size="16" /></span>Verify</span><span class="workflow-caption">EVIDENCE IN CONTEXT</span></div>
          <SearchComposer ref="composer" v-model:question="question" v-model:confirmed="confirmed" :running="running" :compact="!!result || running || !!submittedQuestion" :ready="ready" :can-run="canRun" :error="error" @submit="submit" />
          <AnswerPanel :result="result" :running="running" :elapsed="elapsed" :question="submittedQuestion" :error="error" />
          <section v-if="!result && !running && !submittedQuestion" class="examples-section" aria-labelledby="examples-title"><div class="section-heading"><h2 id="examples-title">Try a research question</h2><span>ADDS TO YOUR PROMPT</span></div><div class="sample-grid"><button v-for="sample in samples" :key="sample.title" class="sample-card" @click="useSample(sample.question)"><span class="sample-icon"><AppIcon :name="sample.icon" :size="20" /></span><strong>{{ sample.title }}</strong><span>{{ sample.detail }}</span></button></div></section>
          <div v-if="!result && !running" class="workspace-note"><AppIcon name="shield" :size="19" /><div><strong>Check what supports the answer</strong><p>Review the source passages before relying on an answer. When the evidence is insufficient, TRACE returns Unknown.</p></div></div>
          <div v-if="result" class="question-recap"><span>YOUR QUESTION</span><p>{{ submittedQuestion }}</p></div>
          <footer class="workspace-footer"><span>BM25 · Skill-Augmented Search Agent</span></footer>
        </section>
        <InspectorPanel v-if="view === 'search'" :result="result" :running="running" @open-document="id => documentDialog?.open(id)" />
        <section v-if="view === 'history'" class="wide-page" aria-labelledby="history-title"><div class="page-heading"><div><p class="eyebrow">SESSION HISTORY</p><h1 id="history-title">History</h1><p class="page-description">Revisit the last 10 completed runs from this browser session.</p></div><button class="button secondary" :disabled="!history.length" @click="clearHistory"><AppIcon name="trash" :size="16" />Clear history</button></div><p v-if="storageNotice" class="form-error">{{ storageNotice }}</p><div v-if="!history.length" class="history-empty"><span class="empty-illustration"><AppIcon name="history" :size="38" /></span><h2>No completed runs yet</h2><p>Completed runs will appear here with their answers, sources, and activity.</p><button class="button primary" @click="navigate('search')">Start a new question</button></div><div v-else class="history-list"><button v-for="record in history" :key="record.id" class="history-card" :disabled="running" @click="openRecord(record)"><span class="history-icon"><AppIcon name="file" :size="22" /></span><div class="history-card-main"><span class="history-date">{{ new Date(record.createdAt).toLocaleString('en-US') }}</span><h2>{{ record.question }}</h2><p>{{ record.result.answer }}</p><div class="history-meta"><span>{{ formatNumber(record.result.tool_calls) }} {{ record.result.tool_calls === 1 ? 'tool call' : 'tool calls' }}</span><span>{{ formatNumber(record.result.total_tokens) }} {{ record.result.total_tokens === 1 ? 'token' : 'tokens' }}</span><span>{{ formatTime(record.result.elapsed_seconds) }}</span></div></div><span class="status-pill" :class="resultStatus(record.result).tone">{{ resultStatus(record.result).label }}</span><AppIcon name="chevron" :size="18" /></button></div></section>
        <section v-if="view === 'baseline'" class="wide-page" aria-labelledby="baseline-title"><div class="page-heading"><div><p class="eyebrow">BASELINE & SERVICE</p><h1 id="baseline-title">Research configuration</h1><p class="page-description">Inspect the retrieval settings, model configuration, and limits reported by the running backend.</p></div><button class="button secondary" :disabled="checkingHealth" @click="refreshHealth"><AppIcon name="refresh" :size="16" />Refresh status</button></div><div class="baseline-service-card"><span class="baseline-service-icon"><AppIcon name="layers" :size="30" /></span><div><h2>BM25 retrieval</h2><p>SQLite FTS5 · Query variants · RRF fusion · Interleaved rankings</p></div><span class="status-pill" :class="ready ? 'success' : 'warning'">{{ serviceLabel }}</span></div><div class="readiness-grid"><div class="readiness-card"><AppIcon name="file" :size="22" /><h3>Corpus index</h3><span class="status-pill" :class="health?.bm25_ready ? 'success' : 'warning'">{{ healthError ? 'Unavailable' : health?.bm25_ready ? 'Ready' : 'Not indexed' }}</span><p>{{ health?.corpus_documents == null ? 'Document count unavailable' : `${formatNumber(health.corpus_documents)} indexed documents` }}</p></div><div class="readiness-card"><AppIcon name="spark" :size="22" /><h3>Model service</h3><span class="status-pill" :class="health?.llm_configured ? 'success' : 'warning'">{{ healthError ? 'Unavailable' : health?.llm_configured ? 'Configured' : 'Not configured' }}</span><p>{{ healthError ? 'Backend connection unavailable' : health?.model || 'Model name unavailable' }}</p></div></div><section class="configuration-card"><div class="section-heading"><h2>Runtime settings</h2><span>FROM THE RUNNING BACKEND</span></div><dl class="configuration-grid"><div><dt>Results per query</dt><dd>{{ formatNumber(health?.retrieval_top_k) }}</dd></div><div><dt>Candidate pool</dt><dd>{{ formatNumber(health?.retrieval_candidate_k) }}</dd></div><div><dt>RRF constant</dt><dd>{{ formatNumber(health?.retrieval_rrf_k) }}</dd></div><div><dt>Maximum agent steps</dt><dd>{{ formatNumber(health?.max_agent_steps) }}</dd></div><div><dt>Maximum tool calls</dt><dd>{{ formatNumber(health?.max_tool_calls) }}</dd></div><div><dt>Consecutive stalled rounds</dt><dd>{{ formatNumber(health?.max_stalled_searches) }}</dd></div><div class="configuration-wide"><dt>Per-question token threshold</dt><dd>{{ health?.max_total_tokens_per_run === 0 ? 'Disabled' : formatNumber(health?.max_total_tokens_per_run) }}</dd></div></dl></section><section class="baseline-evaluation"><div><span class="eyebrow">HISTORICAL VALIDATION</span><h2>40<span>/ 94</span></h2><p>Correct answers in the historical validation run</p></div><div><h3>42.55% normalized exact match</h3><p>The validation run completed 94 of 100 planned questions before reaching its batch budget. This historical result covers only those 94 questions; it is not a new evaluation or a full-set score.</p><span>Methodology: docs/evaluation.md</span></div></section><p class="baseline-guidance"><AppIcon name="info" :size="17" />Model credentials and index paths are configured on the backend. The frontend does not request or store API keys.</p></section>
      </main>
    </div>
  </div>
  <DocumentDialog ref="documentDialog" />
  <dialog ref="helpDialog" class="help-dialog" aria-labelledby="help-title"><header class="dialog-header"><div><span class="eyebrow">QUICK START</span><h2 id="help-title">Work through a question</h2></div><button class="icon-button" aria-label="Close quick guide" @click="helpDialog?.close()"><AppIcon name="close" /></button></header><div class="help-content"><div><AppIcon name="search" :size="23" /><h3>Start with a specific question</h3><p>Describe what you want to establish and include the relevant clues. Suggested questions populate the editor without starting a run.</p></div><div><AppIcon name="check" :size="23" /><h3>Confirm and run</h3><p>Confirm model usage, then select Start research or press Ctrl / Command + Enter. Only one run can be submitted at a time.</p></div><div><AppIcon name="shield" :size="23" /><h3>Follow the evidence</h3><p>Read the source excerpts and open the original documents to check context. Use Activity and Skills to review how the agent approached the question.</p></div><p class="help-notice">History is stored for this browser session only. Closing or refreshing the page does not cancel an active backend run. Cancellation is not currently supported.</p></div></dialog>
</template>
